"""Four post-capture product previews. Fictional, browser-local, never live AI.
Owner's artwork belongs only to the existing brand marks and closing.
"""
from html import escape


def render(t, a, button, icon):
    def ctl(label, attr='', cls='pc-control'):
        return f'<button type="button" class="{cls}" {attr} disabled>{label}</button>'

    def sample(zh, en):
        return escape(t(zh, en))

    nav = f'''<div class="paia-core" data-core-preview data-locale="{t('zh','en')}">
<nav class="pc-nav wrap" aria-label="{t('从输入到上下文','From input to context')}">
<span class="pc-nav-label">{t('收集之后，你说过的话还能继续用。','After capture, what you said stays usable.')}</span>
<a href="#input-library"><span>02</span>{t('查看与编辑','Review & edit')}</a>
<a href="#prompt-reuse"><span>03</span>{t('提示词复用','Prompt reuse')}</a>
<a href="#thought-library"><span>04</span>{t('思想库','Thought Library')}</a>
<a href="#personal-context"><span>05</span>{t('个人上下文','Personal context')}</a>
</nav>
<div class="pc-disclosure wrap"><span class="pc-dot"></span><p>{t('以下为可操作的产品示意，使用虚构数据，不连接你的档案或任何 AI。','Interactive product previews with fictional data. No connection to your archive or any AI.')}</p>{a('status.html',t('内测与规划范围 ↗','Beta & planned scope ↗'))}</div>
<noscript><p class="wrap pc-noscript">{t('以下为静态示意；启用 JavaScript 可在本页尝试操作。','These previews are readable without JavaScript. Enable it to try the local interactions.')}</p></noscript>'''

    records = [
        ('a', '09:42', t('先比较素材找回和内容生成，看看创作者更需要什么。', 'Compare material retrieval with content generation. Find out what creators need most.')),
        ('b', '11:18', t('第一版只解决一个反复发生的问题，不做多人协作。', 'Solve one recurring problem in the first release. Leave collaboration for later.')),
        ('c', '18:03', t('判断标准不是功能多少，而是下一次任务能否接上这次积累。', 'Success is not more features. It is whether the next task can build on this one.')),
    ]
    entries = ''.join(f'''<article class="pc-record" data-input="{key}"><div class="pc-record-meta"><time><span>{["12 AUG", "26 AUG", "10 SEP"][i]}</span>{time}</time><span>0{i+1}</span></div><label class="visually-hidden" for="pc-input-{key}">{t('编辑示例输入','Edit example input')} {i+1}</label><textarea id="pc-input-{key}" data-working="{key}" rows="2" maxlength="1500" spellcheck="false" disabled>{escape(text)}</textarea></article>''' for i, (key, time, text) in enumerate(records))
    originals = ''.join(f'<p data-original="{key}">{escape(text)}</p>' for key, _, text in records)
    library = f'''<section class="pc-section pc-review wrap" id="input-library" aria-labelledby="pc-review-title">
<div class="pc-heading"><div><p class="eyebrow">02 / INPUT ARCHIVE</p><h2 id="pc-review-title">{t('找回你的输入，<br>直接修改。','Find your inputs.<br>Edit them directly.')}</h2></div><div class="pc-intro"><p>{t('按对话、时间或来源找到过去的输入。连续查看，直接修改你要保留的版本；原始来源仍然可以核对。','Find past inputs by conversation, time or source. Read them continuously and edit the version you want to keep; the original source remains available.')}</p><span class="pc-instruction">{t('试着直接修改下面的文字','Try editing the words below')} <span aria-hidden="true">↙</span></span></div></div>
<div class="pc-editor-stage pc-reveal">
<div class="pc-editor"><aside class="pc-sidebar"><span class="pc-app-name">PAIA <span>/ ARCHIVE</span></span><div class="pc-side-label">{t('项目','PROJECTS')}</div><div class="pc-project">⌄ <span>{t('产品探索','Product exploration')}</span></div><div class="pc-current-window"><span class="pc-dot"></span>{t('第一版应该做什么','What belongs in v1')}</div><div class="pc-side-muted">{t('用户研究','User research')}</div><div class="pc-side-muted">{t('想法与取舍','Ideas & trade-offs')}</div><div class="pc-side-bottom">{icon('note','art-icon')}<span>{t('输入属于你。<br>不只属于某个对话。','Your inputs belong to you.<br>Not just to a conversation.')}</span></div></aside>
<div class="pc-reader"><header class="pc-reader-head"><span>{t('产品探索 / 第一版应该做什么','Product exploration / What belongs in v1')}</span><span class="pc-origin-chip">ChatGPT</span></header><div class="pc-reader-tools"><label class="pc-search">{icon('search','mini-icon')}<input type="search" data-archive-search placeholder="{t('搜索本窗口','Search this conversation')}" aria-label="{t('搜索示例窗口','Search the example conversation')}" disabled></label>{ctl('↕ <span>'+t('时间顺序','Time order')+'</span>','data-sort aria-label="'+t('切换时间顺序','Reverse chronological order')+'"','pc-quiet')}</div><div class="pc-document"><p class="pc-date">AUG — SEP 2026</p><h3>{t('第一版应该做什么','What belongs in v1')}</h3><div data-records>{entries}</div><p class="pc-empty" data-archive-empty hidden>{t('没有匹配的输入。试试其他关键词。','No matching inputs. Try a different word.')}</p><details class="pc-source"><summary>{t('原始来源','Original source')}</summary><div>{originals}</div></details></div><footer class="pc-editor-foot"><span data-edit-status role="status">{t('工作版本 · 可直接编辑','Working version · Edit directly')}</span>{ctl(t('还原示例','Reset example'),'data-reset-inputs','pc-quiet')}</footer></div>
</div><div class="pc-version-chip"><span class="pc-check">✓</span><div><strong>{t('改的是工作版本','Edit the working version')}</strong><span>{t('原始来源，仍然保留。','The original stays intact.')}</span></div><span class="pc-version-no">v.02</span></div>
</div><div class="pc-section-foot"><span>{t('查找 → 编辑 → 再利用','FIND → EDIT → REUSE')}</span><p>{t('主题中的对应文字也会随本页编辑更新。','The corresponding words in the topic below update with your edits.')}</p></div>
</section>'''

    prompt_data = [
        (t('结合我的实际约束重新分析。','Re-evaluate this using my actual constraints.'),18,3),
        (t('给出最强的反例和遗漏变量。','Give the strongest counterexample and missing variables.'),12,2),
        (t('把结论转成三个具体的下一步。','Turn the conclusion into three specific next steps.'),8,2),
    ]
    prompt_rows = ''.join(f'''<div class="pc-prompt-row" data-prompt-row="{i}"><div class="pc-prompt-rank"><span data-rank>{i+1:02d}</span><span class="pc-grip" aria-hidden="true">⠿</span></div><div class="pc-prompt-wording"><label class="visually-hidden" for="pc-prompt-{i}">{t('编辑常用提示词','Edit frequent prompt')} {i+1}</label><textarea id="pc-prompt-{i}" data-prompt-text rows="2" maxlength="350" disabled>{escape(text)}</textarea><span>{t(f'使用 {uses} 次 · {variants} 种相似表达 · 预设去重组', f'{uses} uses · {variants} similar wordings · preset group')}</span></div><div class="pc-prompt-actions">{ctl('↑','data-move="-1" aria-label="'+t('上移提示词','Move prompt up')+'"','pc-tiny')}{ctl('↓','data-move="1" aria-label="'+t('下移提示词','Move prompt down')+'"','pc-tiny')}{ctl(t('固定','Pin'),'data-pin aria-pressed="false" aria-label="'+t('固定提示词','Pin prompt')+'"','pc-pin')}{ctl('↗','data-insert aria-label="'+t('填入示例输入框','Insert into example composer')+'"','pc-insert')}</div></div>''' for i,(text,uses,variants) in enumerate(prompt_data))
    prompts = f'''<section class="pc-section pc-prompts" id="prompt-reuse" aria-labelledby="pc-prompts-title"><div class="wrap pc-split">
<div class="pc-prompt-copy"><p class="eyebrow">03 / PERSONAL PROMPTS</p><h2 id="pc-prompts-title">{t('复用真正会再次使用的<br>提示词。','Reuse prompts<br>that already work.')}</h2><p class="pc-body-copy">{t('PAIA 找出你最常使用的提示词，把相似表达归在一起。你可以修改、排序和固定；AI 回复后，还可以选择下一步提示，但不会自动发送。','PAIA finds the prompts you use most, groups similar versions, and lets you edit, reorder or pin them. After an AI reply, it can also suggest a useful next prompt—without sending anything for you.')}</p><div class="pc-prompt-mechanics"><div><span>01</span><strong>{t('收拢相似表达','Group similar wordings · preset group')}</strong></div><div><span>02</span><strong>{t('保留自己的顺序','Keep your own order')}</strong></div><div><span>03</span><strong>{t('一键填入，自己发送','Insert, then choose to send')}</strong></div></div><p class="pc-plan-note"><span>{t('规划中','PLANNED')}</span>{t('经你允许，结合 AI 的回答建议下一步。本页仅演示预设建议，不读取任何真实对话。','With your permission, suggest a next step from the AI’s answer. This page shows a preset, not a live conversation.')}</p></div>
<div class="pc-prompt-scene pc-reveal"><div class="pc-answer"><div class="pc-window-bar"><span class="pc-dot"></span><span>{t('对话示意','EXAMPLE CONVERSATION')}</span><span>↗</span></div><div class="pc-answer-body"><span class="pc-ai-glyph">✳</span><p>{t('先比较两个方向：帮助创作者找回已有素材，或继续增加生成能力。下一步，可以按你的约束做取舍。','Compare two directions: helping creators recover existing material, or adding generation features. Next, weigh them against your constraints.')}</p><span class="pc-answer-end">{t('回答结束','Response complete')} <i></i></span></div></div>
<div class="pc-palette"><header><span class="pc-app-name">PAIA <span>/ PROMPTS</span></span><span class="pc-local-tag">{t('提示词库 · 规划示意','PROMPT LIBRARY · PLANNED')}</span></header><div data-prompt-list>{prompt_rows}</div><div class="pc-suggestion"><span class="pc-suggestion-label">{t('回复后的建议 · 预设示意','AFTER THE AI REPLY · PRESET')}</span><small class="pc-local-tag">{t('新候选示例；也可选择上方已有提示词','A new candidate example, or choose a saved prompt above')}</small>{ctl(t('按我的约束，比较这两个方向。','Compare both directions using my constraints.'),'data-suggestion','pc-suggestion-button')}</div><footer>{t('直接改写 · 拖动或用箭头排序 · ↗ 填入','Edit directly · Drag or use arrows to reorder · ↗ Insert')}</footer></div>
<div class="pc-composer"><label for="pc-composer">{t('下一条输入','YOUR NEXT INPUT')}</label><textarea id="pc-composer" rows="2" maxlength="1000" placeholder="{t('点一条常用表达，填入这里…','Choose a prompt to insert here…')}" disabled></textarea><div><span data-prompt-status role="status">{t('只填入，不自动发送','Inserts only. Never sends automatically.')}</span><span class="pc-send-decoration" aria-hidden="true">↑</span></div></div>
</div></div></section>'''

    trails = [
        ('a','12 AUG','09:42','ChatGPT',records[0][2]),
        ('b','26 AUG','11:18','ChatGPT',records[1][2]),
        ('c','10 SEP','18:03','ChatGPT',records[2][2]),
        ('note','24 SEP','10:26','ChatGPT',t('保留这个取舍：先找回，再决定是否创造更多。','Keep this trade-off: recover first, then decide whether to create more.')),
    ]
    trail_cards=''.join(f'''<article class="pc-thought" data-thought="{key}"><div class="pc-thought-stamp"><time>{date} <span>{time}</span></time><span>{source}</span></div><p data-thought-text="{key}">{escape(text)}</p><div class="pc-topic-source">{t(["窗口：第一版应该做什么 · 最初的问题","窗口：第一版应该做什么 · 缩小范围","窗口：第一版应该做什么 · 判断标准","窗口：用户研究 · 保留的决定"][i],["Conversation: What belongs in v1 · First question","Conversation: What belongs in v1 · Narrowing the scope","Conversation: What belongs in v1 · Decision criterion","Conversation: User research · Decision retained"][i])}</div><span class="pc-thought-order">0{i+1}</span></article>''' for i,(key,date,time,source,text) in enumerate(trails))
    topics=f'''<section class="pc-section pc-topics wrap" id="thought-library" aria-labelledby="pc-topics-title"><div class="pc-heading"><div><p class="eyebrow">04 / THOUGHT LIBRARY</p><h2 id="pc-topics-title">{t('一个主题，<br>看见一路怎么想。','Follow one topic<br>across conversations.')}</h2></div><div class="pc-intro"><p>{t('PAIA 把不同对话里相关的输入整理到同一个主题，并保留时间顺序。你可以看到一个想法一路怎么变化，保留自己的原话，也可以在需要时完整导出。','PAIA groups related inputs from different conversations into one topic and keeps their timeline. See how an idea developed, keep your own wording, and export the record when you need it.')}</p><span class="pc-instruction">{t('切换视图，看同一批原话重新组织','Switch views. See the same words reorganized.')} <span aria-hidden="true">↙</span></span></div></div>
<div class="pc-topic-stage pc-reveal" data-topic-stage><header class="pc-topic-toolbar"><div class="pc-view-switch" role="group" aria-label="{t('示例组织方式','Example organization')}">{ctl(t('分散的输入','Separate inputs'),'data-topic-view="separate" aria-pressed="true"','pc-view')}{ctl(t('按主题串联','Connect by topic'),'data-topic-view="connected" aria-pressed="false"','pc-view')}</div><span class="pc-local-tag">{t('预设分类 · 非实时 AI','PRESET GROUPING · NOT LIVE AI')}</span></header>
<div class="pc-topic-canvas"><div class="pc-topic-identity"><div class="pc-topic-list" aria-label="{t('主题列表','Topic list')}"><span aria-current="true">{t('产品的第一步 · 4','A product’s first step · 4')}</span><details><summary>{t('写作习惯 · 0','Writing practice · 0')}</summary><p>{t('此示例尚无输入。','No inputs in this example yet.')}</p></details><details><summary>{t('学习计划 · 0','Learning plans · 0')}</summary><p>{t('此示例尚无输入。','No inputs in this example yet.')}</p></details></div><div class="pc-topic-symbol">{icon('topic','art-icon')}</div><span class="pc-topic-kicker">{t('主题','TOPIC')} / 01</span><h3>{t('产品的第一步','A product’s first step')}</h3><p>{t('4 条输入<br>1 条持续的思路','4 inputs<br>1 evolving line of thought')}</p><div class="pc-topic-baseline"><span></span><span></span><span></span><span></span></div></div><div class="pc-thoughts">{trail_cards}</div></div>
<footer class="pc-topic-footer"><span data-topic-status role="status">{t('同一个主题，散落在不同时间。','One topic, scattered across different moments.')}</span>{ctl(t('导出这条思路 ↓','Export this line of thought ↓'),'data-topic-export','pc-control')}</footer></div>
<div class="pc-section-foot"><span>{t('原话 → 主题 → 思考历程','YOUR WORDS → TOPIC → EVOLUTION')}</span><p>{t('本页导出为 Markdown，包含你刚刚编辑的工作版本。','The Markdown export includes the working text you just edited.')}</p></div></section>'''

    context=f'''<section class="pc-section pc-context" id="personal-context" aria-labelledby="pc-context-title"><div class="wrap"><div class="pc-heading"><div><p class="eyebrow">05 / PERSONAL CONTEXT</p><h2 id="pc-context-title">{t('决定 AI 可以使用哪些<br>关于你的信息。','Control the context<br>AI can use.')}</h2></div><div class="pc-intro"><p>{t('PAIA 可以从你的输入中提出个人信息候选，由你确认；你也可以自己补充。每条信息都显示来源、确认状态和授权范围。规划中的连接只会把你为当前任务明确授权的内容提供给 AI。','PAIA can suggest personal context from your inputs for you to confirm, and you can add information yourself. Each item shows its source, confirmation state and permission scope. In planned connections, AI receives only what you explicitly approve for the current task.')}</p><span class="pc-instruction">{t('试着选择信息、预览授权，再撤回','Select context, preview access, then revoke it.')} <span aria-hidden="true">↙</span></span></div></div>
<div class="pc-context-stage pc-reveal"><div class="pc-facts"><header><span class="pc-app-name">PAIA <span>/ CONTEXT</span></span><span class="pc-local-tag">{t('个人信息','PERSONAL INFORMATION')}</span></header>
<article class="pc-fact"><div class="pc-fact-title"><label><input type="checkbox" data-context-item="preference" disabled><strong>{t('沟通偏好','Communication preference')}</strong></label><span class="pc-fact-origin">{t('你补充的','ADDED BY YOU')}</span></div><label class="visually-hidden" for="pc-personal-note">{t('编辑个人偏好示例','Edit the personal preference example')}</label><textarea id="pc-personal-note" rows="2" maxlength="500" disabled>{sample('先给结论，再展开依据。','Lead with the conclusion, then explain the evidence.')}</textarea><small>{t('你可以直接修改这条信息。','You can edit this information directly.')}</small></article>
<article class="pc-fact"><div class="pc-fact-title"><label><input type="checkbox" data-context-item="project" disabled><strong>{t('当前项目','Current project')}</strong></label><span class="pc-fact-origin">{t('来自输入 · 已确认','FROM INPUTS · CONFIRMED')}</span></div><p data-context-project>{t('正在探索一个帮助创作者找回已有素材的产品。','Exploring a product that helps creators recover their existing material.')}</p><details><summary>{t('来源与确认记录','Source & confirmation')}</summary><p>{t('示例：3 条产品探索输入。由用户确认，仍可取消本次选用。','Example: 3 product-exploration inputs. Confirmed by the user; selection can still be removed.')}</p></details></article>
<article class="pc-fact pc-pending" data-pending-fact><div class="pc-fact-title"><label><input type="checkbox" data-context-item="candidate" data-await-confirmation disabled><strong>{t('工作方式','Working preference')}</strong></label><span class="pc-fact-origin" data-candidate-badge>{t('提取候选 · 待确认','EXTRACTED CANDIDATE')}</span></div><p data-context-candidate>{t('更倾向于先验证一个小范围方案。','Prefers validating a small-scope version first.')}</p><details><summary>{t("候选来源", "Candidate source")}</summary><p>{t("示例输入：第一版只解决一个反复发生的问题，不做多人协作。窗口：第一版应该做什么，8 月 26 日 11:18。推断尚未确认。", "Example input: Solve one recurring problem in the first release. Leave collaboration for later. Conversation: What belongs in v1, 26 Aug at 11:18. Inference not yet confirmed.")}</p></details><div class="pc-candidate-footer"><small data-candidate-note>{t('候选不是事实，确认前不可选用。','A suggestion is not a fact. Confirm it before use.')}</small>{ctl(t('确认这条信息','Confirm this information'),'data-confirm-candidate','pc-quiet')}</div></article>
</div><aside class="pc-access"><div class="pc-access-route"><span class="pc-route-node">PAIA</span><div class="pc-route-line"><i></i></div><span class="pc-route-node">AI</span></div><div class="pc-access-heading"><span class="pc-local-tag">{t('授权示意 · 尚无真实连接','ACCESS PREVIEW · NO LIVE CONNECTION')}</span><h3>{t('只给这次任务<br>需要的部分。','Just what this<br>task needs.')}</h3><p>{t('请求方：AI 助手（示例）· 任务：比较两个产品方向','Requester: AI assistant (example) · Task: compare two product directions')}</p></div><p class="pc-local-tag">{t("请求上下文 → 预览 → 仅授权项 → 可撤回", "REQUEST → PREVIEW → APPROVED ITEMS ONLY → REVOKE")}</p><div class="pc-scope"><span>{t('范围','SCOPE')}</span><strong>{t('仅本次任务','This task only')}</strong></div><div class="pc-context-preview" data-context-preview><p>{t('尚未选择信息。','No information selected.')}</p></div><div class="pc-access-bottom"><span data-access-state role="status">{t('0 条已选 · 尚未授权','0 selected · Not authorized')}</span>{ctl(t('预览并授权示例','Preview & authorize example'),'data-authorize','pc-authorize')}{ctl(t('撤回本次示例授权','Revoke example access'),'data-revoke hidden','pc-revoke')}</div><dl class="pc-current-use"><dt>{t("当前使用", "Current use")}</dt><dd>{t("未连接 AI · 实际读取 0 条", "No AI connected · 0 items read")}</dd><dt>{t("最近使用", "Last used")}</dt><dd>{t("尚未使用；本页只记录示例授权操作", "Never used; this page records example permission actions only")}</dd></dl><details class="pc-usage"><summary>{t('查看本页操作记录','View this page’s activity')}</summary><ol data-usage-log><li>{t('没有授权或发送记录。','No authorizations or transmissions.')}</li></ol></details><p class="pc-access-boundary">{t('规划中的连接体验。此演示不向 AI 发送任何内容，不保存到你的档案。','A preview of planned connections. Nothing is sent to AI or saved to your archive.')}</p></aside></div>
<div class="pc-section-foot"><span>{t('提出 → 确认 → 授权 → 可撤回','SUGGEST → CONFIRM → AUTHORIZE → REVOKE')}</span><p>{t('个人上下文是你允许 AI 了解的部分，不是一份隐藏的画像。','Personal context is what you allow AI to know. Not a hidden profile.')}</p></div></div></section>'''

    close = f'''<section class="core-close"><div class="core-close-inner wrap"><div><p class="eyebrow">{t('你的输入始终属于你','YOUR INPUTS STAY YOURS')}</p><h2>{t('保存你对 AI 说过的话。<br>决定下一次 AI 可以使用什么。','Keep what you tell AI.<br>Decide what AI can use next.')}</h2><p>{t('PAIA 让你的输入可以长期查看和复用，也让个人上下文始终可见、可改、可授权、可带走。当前内测能力与规划项以状态页为准。','PAIA keeps your inputs usable and your personal context explicit. Review it, change it, authorize it, or take it with you. See the status page for current beta capabilities and planned features.')}</p><div class="actions">{button('beta.html',t('申请内测','Get early access'))}{a('status.html',t('查看当前状态','See current status'),'text-link')}</div></div><div class="core-close-mark"><img src="/assets/website/brand/paia-logo-v1.webp" width="480" height="480" alt="PAIA" loading="lazy" decoding="async"></div></div></section>'''
    return nav+library+prompts+topics+context+'</div>'+close
